try {
  await pane.kill();
} catch (error) {
  if (error instanceof TmuxServerRestartedError) {
    // Read the server again; this pane's id belongs to another daemon now.
  }
}

import { PaneDirection } from "libtmux";
const created = await pane.split({ direction: PaneDirection.Below });
created.id;

import { encodeWhereDocument } from "libtmux";
const encoded = encodeWhereDocument({
  model: "pane",
  version: 1,
  where: { title: { contains: "log" } },
});

import { decodeWhereDocument } from "libtmux/selection";
const document = decodeWhereDocument(
  JSON.parse('{"model":"pane","version":1,"where":{"pane_title":"logs"}}'),
);
if (document.model === "pane") snapshot.panes.where(document.where);

import { parseLegacyWhere } from "libtmux/selection";
const document = parseLegacyWhere("window", { name__contains: "log" });
snapshot.windows.where(document.where);

const traced = new Server({
  onInvocation: (report) => {
    console.log(report.commands[0]?.[0], report.durationMs, report.delivery);
  },
});

const opened = await server.withConnection(async (live) => {
  await session.newWindow({ name: "build" });
  return live.waitFor((current) => current.windows.exists({ name: "build" }));
});
opened.windows.count({ name: "build" }); // 1

await using events = server.watch();
for await (const event of events) {
  if (event.kind === "window-add") console.log(event.windowId);
}

await using live = await server.connect();
for await (const event of live.subscribe()) {
  if (event.kind === "window-add") console.log((await live.snapshot()).windows.count());
}

// One invocation, and every collection agrees with the others.
const now = await server.snapshot();
for (const session of now.sessions) console.log(session.name, session.windows.length);

const before = await server.daemonIdentity();
const after = await server.daemonIdentity();
before.pid === after.pid;

const [editor, logs] = await server.batch([
  session.plan.newWindow({ name: "editor" }),
  session.plan.newWindow({ name: "logs" }),
]);

doc.body:
`session.plan.newWindow(…)` takes what `session.newWindow(…)` takes and
resolves to what it resolves to; it hands the work to {@link Server.batch}
so the planned mutations share one final snapshot.

